package com.shalil.shop;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;
import com.google.android.gms.mlkit.barcode.*;import com.google.mlkit.vision.barcode.common.Barcode;
import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity {
    DB db; LinearLayout root,body,bar; EditText barcodeInput; ArrayList<CartItem> cart=new ArrayList<>(); boolean english=false; String selectedImage=""; long editingInvoice=0;
    final int GREEN=Color.rgb(24,65,51), PALE=Color.rgb(241,246,242);
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);home();}
    String t(String fa,String en){return english?en:fa;}
    TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(8,8,8,8);return v;}
    Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(GREEN));return b;}
    void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(PALE);setContentView(root);bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(10,8,10,8);bar.setBackgroundColor(GREEN);TextView h=text(title,21,Color.WHITE);h.setTypeface(null,1);bar.addView(h,new LinearLayout.LayoutParams(0,-2,1));Button menu=button("☰");menu.setOnClickListener(v->menu());bar.addView(menu);root.addView(bar);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(16,16,16,24);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
    void menu(){String[] opts={t("صفحه اصلی","Home"),t("مدیریت کالاها","Products"),t("فاکتورهای قبلی","Invoices"),t("زبان / Language","Language")};new AlertDialog.Builder(this).setItems(opts,(d,w)->{if(w==0)home();if(w==1)products();if(w==2)invoices();if(w==3){english=!english;home();}}).show();}
    void home(){base(t("نرم افزار شلیل","SHALIL SOFTWARE"));TextView welcome=text(t("به نرم افزار شلیل خوش آمدید","Welcome to Shalil"),20,GREEN);welcome.setGravity(Gravity.CENTER);body.addView(welcome);Button sale=button(t("＋  فاکتور جدید","＋  New invoice"));sale.setTextSize(22);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,150);p.setMargins(0,40,0,18);body.addView(sale,p);sale.setOnClickListener(v->{cart.clear();editingInvoice=0;newInvoice();});Button prod=button(t("مدیریت کالاها","Manage products"));body.addView(prod);prod.setOnClickListener(v->products());Button old=button(t("فاکتورهای قبلی","Previous invoices"));body.addView(old);old.setOnClickListener(v->invoices());}
    void products(){base(t("مدیریت کالاها","Products"));Button add=button(t("＋ افزودن کالای جدید","＋ Add product"));body.addView(add);add.setOnClickListener(v->productDialog(null));Cursor c=db.products();while(c.moveToNext()){long id=c.getLong(0);String name=c.getString(1),code=c.getString(2);double price=c.getDouble(3);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(10,12,10,12);row.setBackgroundColor(Color.WHITE);TextView label=text(name+"\n"+t("بارکد: ","Barcode: ")+code+"\n"+t("قیمت: ","Price: ")+price,16,Color.DKGRAY);row.addView(label);LinearLayout actions=new LinearLayout(this);Button edit=button(t("ویرایش","Edit")),del=button(t("حذف","Delete"));actions.addView(edit,new LinearLayout.LayoutParams(0,-2,1));actions.addView(del,new LinearLayout.LayoutParams(0,-2,1));row.addView(actions);body.addView(row);View space=new View(this);body.addView(space,new LinearLayout.LayoutParams(1,10));edit.setOnClickListener(v->{Cursor x=db.products();while(x.moveToNext())if(x.getLong(0)==id){productDialog(new Product(id,x.getString(1),x.getString(2),x.getDouble(3),x.getString(4)));break;}x.close();});del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(t("این کالا حذف شود؟","Delete this product?")).setPositiveButton(t("حذف","Delete"),(a,b)->{db.deleteProduct(id);products();}).setNegativeButton(t("انصراف","Cancel"),null).show());}c.close();}
    static class Product{long id;String name,code,image;double price;Product(long i,String n,String c,double p,String im){id=i;name=n;code=c;price=p;image=im;}}
    void productDialog(Product old){selectedImage=old==null?"":old.image;LinearLayout box=new LinearLayout(this);box.setPadding(20,8,20,8);box.setOrientation(1);EditText name=new EditText(this),code=new EditText(this),price=new EditText(this);name.setHint(t("نام کالا","Product name"));code.setHint(t("بارکد","Barcode"));price.setHint(t("قیمت","Price"));price.setInputType(8194);if(old!=null){name.setText(old.name);code.setText(old.code);price.setText(""+old.price);}box.addView(name);box.addView(code);box.addView(price);Button photo=button(t("انتخاب عکس کالا","Choose product photo"));box.addView(photo);photo.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,11);});new AlertDialog.Builder(this).setTitle(t("مشخصات کالا","Product details")).setView(box).setPositiveButton(t("ذخیره","Save"),(d,w)->{try{if(name.getText().toString().trim().isEmpty()||price.getText().toString().trim().isEmpty())throw new Exception();db.saveProduct(old==null?0:old.id,name.getText().toString().trim(),code.getText().toString().trim(),Double.parseDouble(price.getText().toString()),selectedImage);products();}catch(Exception e){msg(t("نام و قیمت معتبر وارد کنید","Enter a valid name and price"));}}).setNegativeButton(t("انصراف","Cancel"),null).show();}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==11&&res==RESULT_OK&&data!=null){Uri u=data.getData();selectedImage=u.toString();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}}
    void newInvoice(){base(t("فاکتور فروش جدید","New sales invoice"));TextView tip=text(t("بارکد را وارد یا اسکن کنید","Enter or scan a barcode"),16,GREEN);body.addView(tip);LinearLayout scanrow=new LinearLayout(this);barcodeInput=new EditText(this);barcodeInput.setSingleLine(true);barcodeInput.setHint(t("اسکن / ورود بارکد","Scan / enter barcode"));barcodeInput.setInputType( android.text.InputType.TYPE_CLASS_TEXT);scanrow.addView(barcodeInput,new LinearLayout.LayoutParams(0,-2,1));Button scan=button("▦");scanrow.addView(scan);body.addView(scanrow);scan.setOnClickListener(v->cameraScan());barcodeInput.setImeOptions(EditorInfo.IME_ACTION_DONE);barcodeInput.setOnEditorActionListener((v,a,e)->{String s=barcodeInput.getText().toString().trim();if(!s.isEmpty()){addBarcode(s);barcodeInput.setText("");}return true;});Button addManual=button(t("افزودن با بارکد","Add barcode"));body.addView(addManual);addManual.setOnClickListener(v->{String s=barcodeInput.getText().toString().trim();if(!s.isEmpty()){addBarcode(s);barcodeInput.setText("");}});body.addView(text(t("اقلام فاکتور","Invoice items"),18,GREEN));renderCart();Button finish=button(t("بستن فاکتور و محاسبه مبلغ کل","Close invoice & calculate total"));body.addView(finish);finish.setOnClickListener(v->finishInvoice());}
    void cameraScan(){GmsBarcodeScannerOptions options=new GmsBarcodeScannerOptions.Builder().setBarcodeFormats(Barcode.FORMAT_ALL_FORMATS).build();GmsBarcodeScanning.getClient(this,options).startScan().addOnSuccessListener(b->{if(b.getRawValue()!=null)addBarcode(b.getRawValue());}).addOnFailureListener(e->msg(t("اسکن انجام نشد","Scanning failed")));}
    void addBarcode(String code){Cursor c=db.byBarcode(code);if(c.moveToFirst()){long id=c.getLong(0);String name=c.getString(1);double price=c.getDouble(3);boolean found=false;for(CartItem x:cart)if(x.id==id){x.qty++;found=true;break;}if(!found)cart.add(new CartItem(id,name,price));renderCart();}else msg(t("کالایی با این بارکد پیدا نشد","No product found for this barcode"));c.close();}
    void renderCart(){int start=body.getChildCount(); // rebuild only item section by recreating screen
        // Keep the header and scanner controls, then replace item area
        while(body.getChildCount()>4)body.removeViewAt(4);
        double total=0;for(CartItem x:cart){total+=x.total();LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setBackgroundColor(Color.WHITE);TextView n=text(x.name+"\n"+x.price+" × "+x.qty+" = "+x.total(),15,Color.DKGRAY);r.addView(n,new LinearLayout.LayoutParams(0,-2,1));Button minus=button("−"),plus=button("+"),del=button("×");r.addView(minus);r.addView(plus);r.addView(del);body.addView(r);minus.setOnClickListener(v->{x.qty--;if(x.qty<=0)cart.remove(x);newInvoicePreserve();});plus.setOnClickListener(v->{x.qty++;newInvoicePreserve();});del.setOnClickListener(v->{cart.remove(x);newInvoicePreserve();});}TextView sum=text(t("جمع موقت: ","Subtotal: ")+total,19,GREEN);body.addView(sum);}
    void newInvoicePreserve(){newInvoice();}
    void finishInvoice(){if(cart.isEmpty()){msg(t("فاکتور خالی است","Invoice is empty"));return;}double total=0;for(CartItem x:cart)total+=x.total();final double amount=total;new AlertDialog.Builder(this).setTitle(t("فاکتور بسته شد","Invoice completed")).setMessage(t("مبلغ کل: ","Grand total: ")+amount).setPositiveButton(t("ذخیره فاکتور","Save invoice"),(d,w)->{String date=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date());db.saveInvoice(date,amount,cart);cart.clear();home();}).setNegativeButton(t("بازگشت","Back"),null).show();}
    void invoices(){base(t("فاکتورهای قبلی","Previous invoices"));Cursor c=db.invoices();if(c.getCount()==0)body.addView(text(t("هنوز فاکتوری ثبت نشده است","No invoices yet"),16,Color.GRAY));while(c.moveToNext()){long id=c.getLong(0);String date=c.getString(1);double total=c.getDouble(2);LinearLayout r=new LinearLayout(this);r.setOrientation(1);r.setPadding(10,10,10,10);r.setBackgroundColor(Color.WHITE);r.addView(text(t("فاکتور شماره ","Invoice #")+id+"\n"+date+"\n"+t("مبلغ: ","Total: ")+total,16,Color.DKGRAY));LinearLayout a=new LinearLayout(this);Button view=button(t("مشاهده / ویرایش","View / edit")),del=button(t("حذف","Delete"));a.addView(view,new LinearLayout.LayoutParams(0,-2,1));a.addView(del,new LinearLayout.LayoutParams(0,-2,1));r.addView(a);body.addView(r);View gap=new View(this);body.addView(gap,new LinearLayout.LayoutParams(1,10));view.setOnClickListener(v->invoiceDetail(id,date,total));del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(t("فاکتور حذف شود؟","Delete invoice?")).setPositiveButton(t("حذف","Delete"),(x,y)->{db.deleteInvoice(id);invoices();}).setNegativeButton(t("انصراف","Cancel"),null).show());}c.close();}
    void invoiceDetail(long id,String date,double total){Cursor c=db.invoiceItems(id);StringBuilder s=new StringBuilder(date+"\n\n");ArrayList<CartItem> items=new ArrayList<>();while(c.moveToNext()){s.append(c.getString(3)).append("  × ").append(c.getInt(5)).append("  = ").append(c.getDouble(4)*c.getInt(5)).append("\n");items.add(new CartItem(c.getLong(2),c.getString(3),c.getDouble(4)));items.get(items.size()-1).qty=c.getInt(5);}c.close();s.append("\n").append(t("مبلغ کل: ","Total: ")).append(total);new AlertDialog.Builder(this).setTitle(t("جزئیات فاکتور ","Invoice details ")+id).setMessage(s.toString()).setPositiveButton(t("ویرایش فاکتور","Edit invoice"),(d,w)->{db.deleteInvoice(id);cart=items;newInvoice();}).setNegativeButton(t("بستن","Close"),null).show();}
    void msg(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
